import React, { useState } from 'react';
import axios from 'axios';
import './App.css';

const BACKEND = "http://localhost:8000";

const DEMO_PRODUCTS = [
  { id: 'lays', name: "Lay's Magic Masala", file: "lays.jpg" },
  { id: 'almonds', name: "Smoked Almonds", file: "almonds.jpg" },
  { id: 'lux_soap', name: "Lux Soap", file: "lux_soap.jpg" },
  { id: 'cura', name: "Cura Aamla Ras", file: "cura.jpg" },
  { id: 'natures_essence', name: "Nature's Essence Lotion", file: "natures_essence.jpg" },
  { id: 'dr_sheths', name: "Dr. Sheth's Serum", file: "dr_sheths.jpg" }
];

function App() {
  const [report, setReport] = useState(null);
  const [loading, setLoading] = useState(false);
  const [selectedProduct, setSelectedProduct] = useState(null);
  const [showAiPanel, setShowAiPanel] = useState(false);

  const handleProductSelect = async (product) => {
    setSelectedProduct(product);
    setLoading(true);
    setReport(null);
    setShowAiPanel(false);

    try {
      const imageUrl = `${BACKEND}/uploads/${product.file}`;
      const response = await fetch(imageUrl);

      if (!response.ok) {
        throw new Error(`Image "${product.file}" not found in backend/uploads.`);
      }

      const blob = await response.blob();
      const file = new File([blob], product.file, { type: blob.type });

      const formData = new FormData();
      formData.append("file", file);

      const res = await axios.post(`${BACKEND}/api/analyze`, formData);
      setReport(res.data);
    } catch (err) {
      console.error("Full error:", err);
      const errorMsg = err.response?.data?.detail || err.message || "Unknown error";
      alert(`Error: ${errorMsg}`);
    }
    setLoading(false);
  };

  const getVerdictClass = (overall) => {
    if (!overall) return '';
    return overall.toLowerCase().replace(/\s+/g, '-');
  };

  const formatFieldName = (key) => {
    return key.replace(/_/g, ' ').replace(/\b\w/g, c => c.toUpperCase());
  };

  const renderFieldValue = (key, value) => {
    if (value === null || value === undefined || value === '') return '—';
    if (key === 'mrp_display') return value;
    if (key === 'mrp' && !isNaN(value)) return `₹${value}`;
    return String(value);
  };

  return (
    <div className="app">
      <header>
        <h1>🇮🇳 Legal Metrology Compliance Checker</h1>
        <p>AI-assisted screening of packaged product labels</p>
      </header>

      <div className="demo-grid">
        <h3>Select a Demo Product:</h3>
        <div className="product-buttons">
          {DEMO_PRODUCTS.map(p => (
            <button
              key={p.id}
              onClick={() => handleProductSelect(p)}
              className={selectedProduct?.id === p.id ? 'active' : ''}
              disabled={loading}
            >
              {p.name}
            </button>
          ))}
        </div>
      </div>

      {loading && (
        <div className="loading">
          🔍 Analyzing... running OCR & compliance checks
        </div>
      )}

      {report && !loading && (
        <div className="results">
          {/* ---- SCORE CARD ---- */}
          <div className={`score-card ${getVerdictClass(report.overall)}`}>
            <div className="score">{report.score}/100</div>
            <div className="verdict">{report.overall}</div>
          </div>

          {/* ---- PRODUCT IMAGE + NAME ---- */}
          <div className="product-info">
            <h3>{report.product_name}</h3>
            <img
              src={`${BACKEND}${report.image_url}`}
              alt={report.product_name}
              className="product-image"
            />
          </div>

          {/* ---- VERIFIED COMPLIANCE DATA ---- */}
          <div className="verified-fields">
            <h3>✅ Verified Label Information</h3>
            <p className="subtitle">
              Cross-checked against Indian Legal Metrology Rules, 2011
            </p>
            <table className="fields-table">
              <tbody>
                {Object.entries(report.verified_fields || {}).map(([key, value]) => (
                  <tr key={key}>
                    <td className="field-key">{formatFieldName(key)}</td>
                    <td className="field-value">{renderFieldValue(key, value)}</td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>

          {/* ---- RULE CHECK RESULTS ---- */}
          <div className="rule-results">
            <h3>⚖️ Compliance Rule Check</h3>

            {report.violations && report.violations.length > 0 ? (
              <>
                {report.violations.map((v, i) => (
                  <div key={i} className="violation">
                    <span className="status-icon">🔴</span>
                    <div>
                      <div className="violation-title">
                        <strong>Violation:</strong> {formatFieldName(v.field)}
                      </div>
                      <div className="violation-reason">{v.reason}</div>
                      <div className="citation">📜 {v.citation}</div>
                      <div className="severity">Severity: {v.severity.toUpperCase()}</div>
                    </div>
                  </div>
                ))}
              </>
            ) : (
              <div className="compliant-msg">
                ✅ No violations found — product appears compliant.
              </div>
            )}

            {report.notes && (
              <div className="notes">
                <strong>Inspector Note:</strong> {report.notes}
              </div>
            )}
          </div>

          {/* ---- AI OCR PANEL (COLLAPSIBLE) ---- */}
          {report.ai_extracted_fields && (
            <div className="ai-panel">
              <button
                className="ai-toggle"
                onClick={() => setShowAiPanel(!showAiPanel)}
              >
                {showAiPanel ? '▼' : '▶'} AI OCR Attempt (for reference only)
              </button>
              {showAiPanel && (
                <div className="ai-content">
                  <p className="ai-disclaimer">
                    This shows what the OCR model attempted to read from the label.
                    For glossy/dark labels, OCR may miss fields. The verdict above is
                    based on verified data.
                  </p>
                  {Object.keys(report.ai_extracted_fields).length > 0 ? (
                    <table className="fields-table small">
                      <tbody>
                        {Object.entries(report.ai_extracted_fields).map(([key, val]) => (
                          <tr key={key}>
                            <td className="field-key">{formatFieldName(key)}</td>
                            <td className="field-value">
                              {val?.value || <em>not detected</em>}
                              {val?.confidence !== undefined && (
                                <span className="conf">
                                  {' '}(conf: {(val.confidence * 100).toFixed(0)}%)
                                </span>
                              )}
                            </td>
                          </tr>
                        ))}
                      </tbody>
                    </table>
                  ) : (
                    <p><em>No fields extracted by OCR.</em></p>
                  )}
                </div>
              )}
            </div>
          )}
        </div>
      )}

      <footer>
        <small>
          ⚠️ AI-assisted screening tool. Final compliance decision rests with the
          authorized Legal Metrology inspector.
        </small>
      </footer>
    </div>
  );
}

export default App;
